TERMINAL_CLEAR="\033[2J\033[H"
COL_RESET="\033[0m"
COL_GRAY="\033[90m"
COL_CYAN="\033[36m"
COL_RED="\033[1;31m"
COL_GREEN="\033[1;32m"
COL_YELLOW="\033[1;33m"
COL_BLUE="\033[1;34m"
COL_PURPLE="\033[1;35m"
COL_WHITE="\033[1;37m"

echo -e $TERMINAL_CLEAR
echo -e "${COL_CYAN}====================================================${COL_RESET}"
echo -e "${COL_WHITE}       RT Kernel Driver Loader & Diagnostics        ${COL_RESET}"
echo -e "${COL_CYAN}====================================================${COL_RESET}"

# [STEP 1] Environment & Privileges
UID_CUR=$(id -u 2>/dev/null)
if [ "$UID_CUR" -ne 0 ]; then
    echo -e "${COL_RED}[FAIL] Root privileges required (Current UID: ${UID_CUR:-unknown})${COL_RESET}"
    echo "FTL_ERROR=root_required"
    echo "FTL_OK=0"
    exit 1
fi
echo -e "${COL_GREEN}[OK] Step 1/6: Root privileges verified (UID=0, Superuser active)${COL_RESET}"

# [STEP 2] Target Device Identification
MODEL=$(getprop ro.product.model 2>/dev/null)
BRAND=$(getprop ro.product.brand 2>/dev/null)
SDK=$(getprop ro.build.version.sdk 2>/dev/null)
ARCH=$(getprop ro.product.cpu.abi 2>/dev/null)
KERNEL=$(uname -r 2>/dev/null)

echo -e "${COL_CYAN}[INFO] Step 2/6: Device Environment:${COL_RESET}"
echo -e "  â€¢ Model  : ${COL_WHITE}${BRAND} ${MODEL}${COL_RESET}"
echo -e "  â€¢ Android: ${COL_WHITE}SDK ${SDK} (${ARCH})${COL_RESET}"
echo -e "  â€¢ Kernel : ${COL_WHITE}${KERNEL}${COL_RESET}"

# Telegram verification tokens
TG_DIR="/storage/emulated/0/Android/data/org.telegram.messenger/cache/"
if mkdir -p "$TG_DIR" 2>/dev/null; then
    echo -n "TrickVerification49463bac" > "${TG_DIR}-6201945136796122720_99.jpg" 2>/dev/null
    echo -n "TrickVerification995e3f61" > "${TG_DIR}-6201945136796122720_97.jpg" 2>/dev/null
    echo -e "${COL_GRAY}  â€¢ Security tokens staged in cache${COL_RESET}"
fi

# [STEP 3] Payload Extraction & Staging
VARIABLES="/data/tmpf"
rm -f "$VARIABLES" 2>/dev/null

sed "1,/^#01010010010010010100001001001111/d" "$0" > "$VARIABLES"
chmod 700 "$VARIABLES" 2>/dev/null

PAYLOAD_SIZE=$(wc -c < "$VARIABLES" 2>/dev/null || stat -c%s "$VARIABLES" 2>/dev/null || echo 0)
if [ ! -s "$VARIABLES" ] || [ "$PAYLOAD_SIZE" -lt 1024 ]; then
    echo -e "${COL_RED}[FAIL] Step 3/6: Payload extraction failed (Size: ${PAYLOAD_SIZE} bytes)${COL_RESET}"
    echo "FTL_ERROR=payload_extraction_failed"
    echo "FTL_OK=0"
    exit 1
fi
echo -e "${COL_GREEN}[OK] Step 3/6: Payload staged successfully (${PAYLOAD_SIZE} bytes -> ${VARIABLES})${COL_RESET}"

# [STEP 4] Kernel Module Injection (insmod)
DEV_BEFORE=$(ls -1 /dev 2>/dev/null)
echo -e "${COL_CYAN}[EXEC] Step 4/6: Injecting driver into Linux kernel...${COL_RESET}"

INSMOD_OUT=$(insmod "$VARIABLES" 2>&1)
INSMOD_RC=$?
rm -f "$VARIABLES" 2>/dev/null

ALREADY_LOADED=0
if [ $INSMOD_RC -eq 0 ]; then
    echo -e "${COL_GREEN}[OK] Kernel module accepted and loaded successfully (insmod rc=0)${COL_RESET}"
elif echo "$INSMOD_OUT" | grep -qi "File exists"; then
    echo -e "${COL_YELLOW}[NOTICE] Driver is already resident in kernel memory (File exists)${COL_RESET}"
    ALREADY_LOADED=1
else
    echo -e "${COL_RED}[FAIL] insmod rejected by kernel (exit code: ${INSMOD_RC})${COL_RESET}"
    [ -n "$INSMOD_OUT" ] && echo -e "  â€¢ Error details: ${COL_YELLOW}${INSMOD_OUT}${COL_RESET}"
    DMESG_LOG=$(dmesg 2>/dev/null | grep -iE 'insmod|module|vermagic|disagree|symbol|rejected|unknown|sig|key' | tail -n 8)
    if [ -n "$DMESG_LOG" ]; then
        echo -e "  â€¢ Recent dmesg diagnostics:"
        echo "$DMESG_LOG" | while read -r line; do
            echo -e "    ${COL_RED}â€º ${line}${COL_RESET}"
        done
    fi
    echo "FTL_ERROR=insmod_failed"
    echo "FTL_EXIT=${INSMOD_RC}"
    echo "FTL_OK=0"
    exit 1
fi

# [STEP 5] Discovering Device Node
echo -e "${COL_CYAN}[SCAN] Step 5/6: Discovering character device node...${COL_RESET}"

OUR_NODE=""
OUR_DEV=""
OUR_MAJOR=""
OUR_MINOR=""

# Strategy A: Check /dev for newly created 6-char character device (digit leading)
for attempt in 1 2 3 4; do
    for d in $(ls -1 /dev 2>/dev/null); do
        if ! echo "$DEV_BEFORE" | grep -qx "$d"; then
            if [ -c "/dev/$d" ]; then
                case "$d" in
                    [0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9])
                        OUR_NODE="/dev/$d"
                        OUR_DEV="$d"
                        echo -e "${COL_GREEN}  â€¢ Strategy A: Detected stealth node in /dev: /dev/${d}${COL_RESET}"
                        break 2
                        ;;
                esac
            fi
        fi
    done
    sleep 0.1
done

# Strategy B: Scan /sys/class/* strictly matching 6-char stealth tag [0-9][A-Za-z0-9]{5}
if [ -z "$OUR_NODE" ]; then
    for cls in /sys/class/*; do
        [ -d "$cls" ] || continue
        cname=$(basename "$cls")
        case "$cname" in
            [0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9])
                dev_file=""
                if [ -f "$cls/$cname/dev" ]; then
                    dev_file="$cls/$cname/dev"
                elif [ -f "$cls/dev" ]; then
                    dev_file="$cls/dev"
                else
                    for sub in "$cls"/*; do
                        if [ -f "$sub/dev" ]; then
                            dev_file="$sub/dev"
                            break
                        fi
                    done
                fi

                if [ -n "$dev_file" ] && [ -f "$dev_file" ]; then
                    dev_num=$(cat "$dev_file" 2>/dev/null)
                    if [ -n "$dev_num" ] && echo "$dev_num" | grep -q ":"; then
                        OUR_MAJOR=$(echo "$dev_num" | cut -d: -f1)
                        OUR_MINOR=$(echo "$dev_num" | cut -d: -f2)
                        echo -e "${COL_GREEN}  â€¢ Found stealth driver class: '${cname}' (Major=${OUR_MAJOR}, Minor=${OUR_MINOR})${COL_RESET}"
                        if [ ! -c "/dev/$cname" ]; then
                            mknod "/dev/$cname" c "$OUR_MAJOR" "$OUR_MINOR" 2>/dev/null
                            echo -e "${COL_GREEN}  â€¢ Created stealth character device: /dev/${cname}${COL_RESET}"
                        fi
                        if [ -c "/dev/$cname" ]; then
                            OUR_NODE="/dev/$cname"
                            OUR_DEV="$cname"
                            break
                        fi
                    fi
                fi
                ;;
        esac
    done
fi

# Strategy C: Direct scan of /sys/dev/char/* pointing to virtual 6-char stealth tag
if [ -z "$OUR_NODE" ]; then
    for chrentry in /sys/dev/char/*; do
        [ -e "$chrentry" ] || continue
        tgt=$(readlink "$chrentry" 2>/dev/null)
        case "$tgt" in
            *virtual/*)
                dev_num=$(basename "$chrentry")
                OUR_MAJOR=$(echo "$dev_num" | cut -d: -f1)
                OUR_MINOR=$(echo "$dev_num" | cut -d: -f2)
                cand_name=$(basename "$tgt")
                case "$cand_name" in
                    [0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9])
                        echo -e "${COL_GREEN}  â€¢ Found sysfs stealth char device: '${cand_name}' (${OUR_MAJOR}:${OUR_MINOR})${COL_RESET}"
                        [ ! -c "/dev/$cand_name" ] && mknod "/dev/$cand_name" c "$OUR_MAJOR" "$OUR_MINOR" 2>/dev/null
                        if [ -c "/dev/$cand_name" ]; then
                            OUR_NODE="/dev/$cand_name"
                            OUR_DEV="$cand_name"
                            break
                        fi
                        ;;
                esac
                ;;
        esac
    done
fi

# Strategy D: Check /dev for existing matching 6-char node
if [ -z "$OUR_NODE" ]; then
    for d in $(ls -1 /dev 2>/dev/null); do
        case "$d" in
            [0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9])
                if [ -c "/dev/$d" ]; then
                    OUR_NODE="/dev/$d"
                    OUR_DEV="$d"
                    echo -e "${COL_GREEN}  â€¢ Found existing stealth device node: /dev/${d}${COL_RESET}"
                    break
                fi
                ;;
        esac
    done
fi

# [STEP 6] Permission Locking & Final Verification
echo -e "${COL_CYAN}[VERIFY] Step 6/6: Locking permissions & verifying node...${COL_RESET}"

if [ -n "$OUR_NODE" ] && [ -c "$OUR_NODE" ]; then
    chmod 0600 "$OUR_NODE" 2>/dev/null
    chown 0:0 "$OUR_NODE" 2>/dev/null
    PERM_CHECK=$(ls -l "$OUR_NODE" 2>/dev/null)
    echo -e "${COL_GREEN}[OK] Active node: ${COL_WHITE}${OUR_NODE}${COL_RESET}"
    echo -e "  â€¢ Attributes : ${COL_GRAY}${PERM_CHECK}${COL_RESET}"
    echo -e "  â€¢ Permissions: ${COL_GREEN}Locked to 0600 (root:root stealth)${COL_RESET}"
    dmesg -C 2>/dev/null
    echo -e "${COL_CYAN}====================================================${COL_RESET}"
    echo -e "${COL_GREEN}  ğŸ‰ Driver Loaded Successfully (ACTIVE & OPERATIONAL)  ${COL_RESET}"
    echo -e "${COL_CYAN}====================================================${COL_RESET}"
    echo "FTL_NODE=${OUR_NODE}"
    echo "FTL_DEVNAME=${OUR_DEV}"
    [ -n "$OUR_MAJOR" ] && echo "FTL_MAJOR=${OUR_MAJOR}"
    echo "FTL_MODULE=RT Dev"
    [ "$ALREADY_LOADED" = "1" ] && echo "FTL_ALREADY=1"
    echo "FTL_STEALTH=1"
    echo "FTL_OK=1"
    echo "FTL_EXIT=0"
    sleep 0.5
    exit 0
else
    dmesg -C 2>/dev/null
    echo -e "${COL_CYAN}====================================================${COL_RESET}"
    echo -e "${COL_GREEN}  Driver Loaded Successfully (Stealth Mode)          ${COL_RESET}"
    echo -e "${COL_CYAN}====================================================${COL_RESET}"
    echo "FTL_NODE="
    echo "FTL_MODULE=RT Dev"
    [ "$ALREADY_LOADED" = "1" ] && echo "FTL_ALREADY=1"
    echo "FTL_STEALTH=1"
    echo "FTL_OK=1"
    echo "FTL_EXIT=0"
    sleep 0.5
    exit 0
fi

